var n=`0256-trahana-soup`;var t=`world-0256`;var a=`CY`;var r=`western-asia`;var l=4;var o=526;var s={en:`Trahana Soup`,ua:`Суп трахана`};var d={en:`A simplified fresh grain-and-yogurt adaptation of traditional fermented trahana; fermented dried trahana is absent from the catalog.`,ua:`Спрощений варіант супу зі свіжої крупи та йогурту; ферментованої сушеної трахани немає в каталозі.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`bulgur`,160,`g`],[`plain-yogurt`,250,`g`],[`all-purpose-flour`,85,`g`],[`table-salt`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 480 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 480 хвилин.`,t:[`rapid-chilling`],m:480,i:[]},{en:`Cook the listed ingredients in simmering water for about 35 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 35 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:35,i:[[`chicken-stock`,1100,`ml`],[`water`,300,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`halloumi`,170,`g`],[`mint`,10,`g`]]}];var u={slug:n,id:t,country:`CY`,region:r,servings:4,minutes:526,title:s,text:d,steps:g};export{a as country,u as default,t as id,o as minutes,r as region,l as servings,n as slug,g as steps,d as text,s as title};